// Storage rules generated by src/ops/firebaseRules.ts (buildStorageRules),
// on the emulator. They read the caller's role from Firestore users/{uid}
// (cross-service rules), so the Firestore emulator must run too.
import { assertFails, assertSucceeds, initializeTestEnvironment } from "@firebase/rules-unit-testing";
import { doc, setDoc } from "firebase/firestore";
import { deleteObject, getBytes, ref, uploadBytes } from "firebase/storage";
import { ADMIN, buildFirestoreRules, buildStorageRules, FIRESTORE, PROJECT, STORAGE, summary, t } from "./rules.mjs";

// Cross-service rules only see the Firestore data of the emulators:exec project.
const projectId = PROJECT;
const e = await initializeTestEnvironment({
  projectId,
  firestore: { rules: buildFirestoreRules({ adminEmail: ADMIN }), ...FIRESTORE },
  storage: { rules: buildStorageRules({ adminEmail: ADMIN, maxUploadMb: 1 }), ...STORAGE },
});
await e.withSecurityRulesDisabled(async (c) => {
  const db = c.firestore();
  await setDoc(doc(db, "users/mia"), { email: "mia@example.com", role: "member", authUid: "mia" });
  await setDoc(doc(db, "users/val"), { email: "val@example.com", role: "viewer", authUid: "val" });
  await setDoc(doc(db, "users/dan"), { email: "dan@example.com", role: "member", authUid: "dan", disabled: true });
});
const as = (uid, email, verified = true) => e.authenticatedContext(uid, { email, email_verified: verified }).storage();
const boss = as("boss", ADMIN);
const mia = as("mia", "mia@example.com");
const val = as("val", "val@example.com");
const dan = as("dan", "dan@example.com");
const eve = as("eve", "eve@evil.test");
const bytes = new Uint8Array([1, 2, 3]);

await t("member uploads a file", assertSucceeds(uploadBytes(ref(mia, "files/f1"), bytes)));
await t("bootstrap admin uploads without a users record", assertSucceeds(uploadBytes(ref(boss, "files/f2"), bytes)));
await t("unverified bootstrap address is not admin", assertFails(uploadBytes(ref(as("boss2", ADMIN, false), "files/f3"), bytes)));
await t("viewer reads a file", assertSucceeds(getBytes(ref(val, "files/f1"))));
await t("viewer cannot upload", assertFails(uploadBytes(ref(val, "files/f4"), bytes)));
await t("disabled member cannot read", assertFails(getBytes(ref(dan, "files/f1"))));
await t("stranger cannot read", assertFails(getBytes(ref(eve, "files/f1"))));
await t("anonymous cannot read", assertFails(getBytes(ref(e.unauthenticatedContext().storage(), "files/f1"))));
await t("file over the size limit is refused", assertFails(uploadBytes(ref(mia, "files/big"), new Uint8Array(1024 * 1024 + 1))));
await t("path-unsafe file id is refused", assertFails(uploadBytes(ref(mia, "files/a.b"), bytes)));
await t("paths outside files/ are closed", assertFails(uploadBytes(ref(mia, "other/f1"), bytes)));
await t("member cannot delete (purge is admin-only)", assertFails(deleteObject(ref(mia, "files/f1"))));
await t("admin deletes a file", assertSucceeds(deleteObject(ref(boss, "files/f1"))));

await e.cleanup();
process.exit(summary("Storage rules") ? 1 : 0);
